S.update({'pl_day': 'நாள்', 'pl_days': 'நாட்கள்', 'pl_month': 'மாதம்', 'pl_months': 'மாதங்கள்', 'pl_year': 'ஆண்டு', 'pl_years': 'ஆண்டுகள்', 'premium_menu': '<b>💎 பிரீமியம் பெறுங்கள்</b>\n\n<b>✨ உங்களுக்கு கிடைப்பவை:</b>\n<b>♾ வரம்பற்ற ஃபைல்கள், தினசரி வரம்பு இல்லை</b>\n<b>🔓 சரிபார்ப்பு தேவையில்லை</b>\n<b>📤 ஃபைல்களை ஃபார்வர்டு / சேமிக்கலாம்</b>\n<b>📦 ஒரே தட்டலில் அனைத்து ஃபைல்கள்</b>\n<b>⏳ ஃபைல்கள் நீண்ட நேரம் இருக்கும்</b>\n<b>🚫 கட்டாய சப்ஸ்கிரைப் இல்லை</b>\n<b>🚀 மூவி கோரிக்கைகளுக்கு முன்னுரிமை</b>\n\n{status}<b>👇 உங்கள் திட்டத்தைத் தேர்ந்தெடுக்கவும்</b>', 'premium_active_line': '<b>✅ உங்கள் பிரீமியம் {until} வரை செயலில் உள்ளது</b>\n<b>மீண்டும் வாங்கினால் நேரம் கூடுதலாக சேரும்.</b>\n\n', 'no_pay_method': '<b>🔧 பிரீமியம் கட்டணம் தற்போது கிடைக்கவில்லை.</b>\n<b>உரிமையாளரைத் தொடர்பு கொள்ளவும்.</b>', 'btn_contact': '💬 உரிமையாளரை தொடர்பு கொள்ள', 'btn_back': '⬅️ பின்', 'btn_cancel': '🚫 ரத்து', 'btn_refer': '🫂 பரிந்துரை & சம்பாதி', 'btn_share': '📤 இணைப்பைப் பகிர்', 'btn_paid': '✅ நான் பணம் செலுத்தினேன்', 'btn_try_again': '🔁 மீண்டும் முயல்', 'btn_renew': '💎 புதுப்பி', 'pay_screen': '<b>💳 ₹{price} செலுத்துங்கள்</b>\n<b>📦 திட்டம்: {dur}</b>\n\n{methods}\n\n<b>📝 3 எளிய படிகள்</b>\n<b>1️⃣ சரியாக ₹{price} செலுத்துங்கள்</b>\n<b>2️⃣ பணம் செலுத்திய ஸ்கிரீன்ஷாட் எடுங்கள்</b>\n<b>3️⃣ “நான் பணம் செலுத்தினேன்” அழுத்தி ஸ்கிரீன்ஷாட்டை அனுப்புங்கள்</b>\n\n<b>⏱ ஒப்புதலுக்குப் பிறகு சில நிமிடங்களில் பிரீமியம் தொடங்கும்.</b>', 'pay_upi_line': '<b>📲 UPI ஐடி:</b> <code>{upi}</code>', 'pay_qr_line': '<b>🖼 அல்லது மேலே உள்ள QR கோடை ஸ்கேன் செய்யுங்கள்</b>', 'send_ss_prompt': '<b>📸 இப்போது பணம் செலுத்திய ஸ்கிரீன்ஷாட்டை அனுப்புங்கள்</b>\n<b>இந்த சாட்டில் புகைப்படமாக அனுப்புங்கள் 👇</b>', 'ss_received': '<b>✅ ஸ்கிரீன்ஷாட் கிடைத்தது!</b>\n<b>⏳ அட்மின் சரிபார்க்கிறார். ஒப்புதல் கிடைத்ததும் இங்கே செய்தி வரும்.</b>', 'ss_pending_exists': '<b>⏳ உங்கள் கட்டணம் ஏற்கனவே சரிபார்ப்பில் உள்ளது.</b>\n<b>அட்மினுக்காகக் காத்திருக்கவும்.</b>', 'ss_duplicate': '<b>⚠️ இந்த ஸ்கிரீன்ஷாட் ஏற்கனவே பயன்படுத்தப்பட்டது.</b>\n<b>உங்கள் சொந்த புதிய ஸ்கிரீன்ஷாட்டை அனுப்புங்கள்.</b>', 'ss_need_photo': '<b>📸 ஸ்கிரீன்ஷாட்டை புகைப்படமாக அனுப்புங்கள்.</b>', 'pay_approved': '<b>🎉 பிரீமியம் செயல்படுத்தப்பட்டது!</b>\n\n<b>📦 திட்டம்: {dur}</b>\n<b>⏰ {until} வரை செல்லும்</b>\n\n<b>வரம்பற்ற ஃபைல்களை அனுபவியுங்கள் 🍿</b>', 'pay_rejected': '<b>❌ கட்டணம் சரிபார்க்கப்படவில்லை</b>\n\n<b>உங்கள் கட்டணத்தைக் கண்டறிய முடியவில்லை. பணம் செலுத்தியிருந்தால் தெளிவான ஸ்கிரீன்ஷாட்டை மீண்டும் அனுப்புங்கள் அல்லது உதவியைத் தொடர்பு கொள்ளுங்கள்.</b>', 'remind_exp': '<b>⏰ உங்கள் பிரீமியம் {left} இல் முடிகிறது!</b>\n<b>வரம்பற்ற அணுகலைத் தொடர இப்போதே புதுப்பிக்கவும் 👇</b>', 'expired_msg': '<b>⌛ உங்கள் பிரீமியம் முடிந்துவிட்டது.</b>\n<b>வரம்பற்ற ஃபைல்களை மீண்டும் பெற எப்போது வேண்டுமானாலும் புதுப்பிக்கலாம் 💎</b>', 'myplan_active': '<b>💎 உங்கள் திட்டம்</b>\n\n<b>✅ பிரீமியம் செயலில் உள்ளது</b>\n<b>⏰ {until} வரை செல்லும்</b>', 'myplan_none': '<b>💎 உங்கள் திட்டம்</b>\n\n<b>நீங்கள் இலவச திட்டத்தில் உள்ளீர்கள்.</b>\n<b>வரம்பற்ற ஃபைல்களுக்கு பிரீமியம் பெறுங்கள் 👇</b>', 'refer_menu': '<b>🫂 பரிந்துரை & சம்பாதி</b>\n\n<b>🎁 {need} நண்பர்களை அழைத்தால் = {days} பிரீமியம் இலவசம்!</b>\n\n<b>🔗 உங்கள் இணைப்பு (நகலெடுக்க தட்டவும்):</b>\n<code>{link}</code>\n\n<b>👥 இணைந்தவர்கள்: {joined}</b>\n<b>✅ கணக்கில் சேர்ந்தவை: {qualified}</b>\n<b>📈 முன்னேற்றம்: {progress}/{need}</b>\n<b>🏆 வென்ற பரிசுகள்: {rewards}</b>\n\n<b>ℹ️ நண்பர் புதிய பயனராக இருந்து தனது முதல் ஃபைலைப் பெற்றால் கணக்கில் சேரும்.</b>', 'refer_off': '<b>🫂 பரிந்துரை திட்டம் இப்போது நிறுத்தப்பட்டுள்ளது.</b>', 'refer_share_text': 'டெலிகிராமில் இலவச படங்கள், தொடர்கள், அனிமே 🍿 என் இணைப்பில் சேருங்கள்!', 'refer_qualified': '<b>🎉 ஒரு நண்பர் இணைந்து ஃபைல் பெற்றார்!</b>\n<b>📈 முன்னேற்றம்: {progress}/{need}</b>', 'refer_reward': '<b>🏆 பரிசு கிடைத்தது!</b>\n\n<b>💎 +{days} பிரீமியம் சேர்க்கப்பட்டது</b>\n<b>⏰ {until} வரை செல்லும்</b>'})

S.update({'start_txt': '<b>🎬 𝗠𝗢𝗩𝗜𝗘 𝗠𝗔𝗦𝗧𝗘𝗥 𝗕𝗢𝗧</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>👋 வணக்கம் {name}, {greet}!</b>\n\n<b>🎬 திரைப்படங்கள் • 📺 வெப் தொடர்கள் • 🍥 அனிமே</b>\n<b>⚡ வேகமான தேடல் • ஸ்மார்ட் வடிகட்டி</b>\n\n<b>📝 படத்தின் பெயரை அனுப்புங்கள் — நான் தேடித் தருகிறேன்!</b>\n\n<b>━━━━━━━━━━━━━━━</b>\n<b>📢 <a href="{updates}">புதிய அப்டேட்கள்</a>  •  💬 <a href="{support}">உதவி</a></b>\n<b>✦ Powered by <a href="{brand}">NeonGhost Network</a></b>', 'about_txt': '<b>🤖 என்னைப் பற்றி</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>• பெயர்:</b> <a href="https://t.me/{bot_user}">{bot_name}</a>\n<b>• உருவாக்கியவர்:</b> <a href="{brand}">NeonGhost Network</a>\n<b>• உதவி:</b> <a href="{support}">உதவி</a>\n\n<b>━━━━━━━━━━━━━━━</b>\n💼 இது கட்டண, தனிப்பட்ட போட்.\nஉங்கள் சேனலுக்கும் இப்படி ஒரு போட் வேண்டுமா?\n👉 <a href="{owner}">உரிமையாளரிடம்</a> பேசுங்கள்', 'premium_menu': '<b>💎 பிரீமியம் பெறுங்கள்</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>✨ உங்களுக்கு கிடைப்பவை:</b>\n<b> ➤ ♾️ வரம்பற்ற ஃபைல்கள், தினசரி வரம்பு இல்லை</b>\n<b> ➤ 🔓 சரிபார்ப்பு தேவையில்லை</b>\n<b> ➤ 📤 ஃபைல்களை ஃபார்வர்டு / சேமிக்கலாம்</b>\n<b> ➤ 📦 ஒரே தட்டலில் அனைத்து ஃபைல்கள்</b>\n<b> ➤ ⏳ ஃபைல்கள் நீண்ட நேரம் இருக்கும்</b>\n<b> ➤ 🚫 கட்டாய சப்ஸ்கிரைப் இல்லை</b>\n<b> ➤ 🚀 மூவி கோரிக்கைகளுக்கு முன்னுரிமை</b>\n\n<b>━━━━━━━━━━━━━━━</b>\n{status}<b>👇 உங்கள் திட்டத்தைத் தேர்ந்தெடுக்கவும்</b>'})

S.update({'ss_doubt': '<b>❓ சந்தேகமா? கீழே தட்டி அட்மினிடம் கேளுங்கள்.</b>', 'btn_contact_admin': '💬 அட்மினைத் தொடர்பு கொள்'})

S.update({'nf_text': '<b>😕 கிடைக்கவில்லை</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>🔎 {title}</b>\n\n<b>இந்தப் படம் இன்னும் எங்கள் நூலகத்தில் இல்லை.</b>\n<b>கீழே தட்டுங்கள், நாங்கள் சேர்ப்போம் 👇</b>', 'btn_request': '📩 இந்தப் படத்தை கோருங்கள்', 'req_sent': '<b>✅ கோரிக்கை அனுப்பப்பட்டது!</b>\n<b>சேர்க்கப்பட்டதும் இங்கே செய்தி அனுப்புவோம்.</b>', 'req_already': '<b>ℹ️ நீங்கள் ஏற்கனவே இதைக் கோரியுள்ளீர்கள்.</b>\n<b>சேர்க்கப்பட்டதும் தெரிவிப்போம்.</b>', 'req_expired': '<b>⌛ மீண்டும் தேடி கோரிக்கை அழுத்துங்கள்.</b>', 'req_up': '<b>🎉 நல்ல செய்தி!</b>\n\n<b>🎬 {title}</b>\n<b>✅ இப்போது சேர்க்கப்பட்டது. கீழே தட்டிப் பெறுங்கள் 👇</b>', 'req_al': '<b>♻️ {title}</b>\n<b>ஏற்கனவே கிடைக்கிறது. மீண்டும் தேடுங்கள் 👇</b>', 'req_un': '<b>⚠️ {title}</b>\n<b>இப்போது கிடைக்கவில்லை. மன்னிக்கவும்!</b>', 'req_nr': '<b>📌 {title}</b>\n<b>இன்னும் வெளியாகவில்லை. வெளியான பின் சேர்க்கப்படும்.</b>', 'req_ws': '<b>♨️ {title}</b>\n<b>எழுத்துப்பிழையைச் சரிபார்த்து (கூகுளில் பாருங்கள்) மீண்டும் தேடுங்கள்.</b>', 'btn_search_now': '🔍 இப்போது தேடு', 'btn_account': '👤 என் கணக்கு', 'btn_prefs': '⚙️ விருப்பங்கள்', 'btn_downloads': '📥 என் பதிவிறக்கங்கள்', 'acc_text': '<b>👤 என் கணக்கு</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>🆔 ஐடி:</b> <code>{uid}</code>\n<b>📦 திட்டம்:</b> {plan}\n<b>📥 இன்று மீதமுள்ள ஃபைல்கள்:</b> {left}\n<b>🫂 பரிந்துரை:</b> {prog}/{need}\n<b>🌐 மொழி:</b> {lang_name}\n<b>🎞 விருப்பம்:</b> {pref}', 'acc_free': 'இலவசம்', 'acc_verified': '✅ சரிபார்க்கப்பட்டது {until} வரை', 'acc_premium': '💎 பிரீமியம் {until} வரை', 'acc_unlimited': '♾ வரம்பற்றது', 'any_label': 'ஏதேனும்', 'pref_text': '<b>⚙️ விருப்பங்கள்</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>🎞 தரம்:</b> {q}\n<b>🗣 மொழி:</b> {l}\n\n<b>ℹ️ முதலில் உங்கள் விருப்பத்தை முயல்வோம்.</b>\n<b>இல்லையெனில் மற்ற அனைத்து ஃபைல்களும் கிடைக்கும்.</b>', 'dl_text': '<b>📥 என் பதிவிறக்கங்கள்</b>\n<b>━━━━━━━━━━━━━━━</b>\n\n<b>உங்கள் கடைசி ஃபைல்கள். மீண்டும் பெற தட்டுங்கள் 👇</b>', 'dl_empty': '<b>📥 இன்னும் பதிவிறக்கங்கள் இல்லை.</b>\n<b>ஒரு படத்தைத் தேடித் தொடங்குங்கள் 🍿</b>', 'lang_then_file': '<b>✅ மொழி சேமிக்கப்பட்டது!</b>\n<b>உங்கள் ஃபைலைப் பெற கீழே தட்டுங்கள் 👇</b>'})
